mapper.update:
update sys_dept
   set parent_id = #{f.parentId}, dept_nm = #{f.deptNm}, sort_no = #{f.sortNo}, use_yn = #{f.useYn},
       head_user_id = #{f.headUserId}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where dept_id = #{deptId} and row_ver = #{f.rowVer}

mapper.select:
select grp_cd, code, code_nm, null as code_nm_key, sort_no, use_yn, false as system_yn, attrs::text as attrs, row_ver
  from sys_comp_code
 where grp_cd = #{grpCd} and code = #{code}

mapper.update:
update sys_comp_code
   set code_nm = #{f.codeNm}, sort_no = #{f.sortNo}, attrs = #{attrs}::jsonb, use_yn = #{f.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where grp_cd = #{grpCd} and code = #{f.code} and row_ver = #{f.rowVer}

update sys_numbering_rule
   set rule_nm = #{f.ruleNm}, pattern = #{f.pattern}, reset_cycle = #{f.resetCycle}, use_yn = #{f.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where rule_cd = #{f.ruleCd} and row_ver = #{f.rowVer}

update sys_comp
   set comp_nm = #{f.compNm}, comp_en_nm = #{f.compEnNm}, biz_no = #{f.bizNo}, ceo_nm = #{f.ceoNm},
       tel_no = #{f.telNo}, addr = #{f.addr}, time_zone = #{f.timeZone}, locale_cd = #{f.localeCd},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where comp_cd = hb_current_comp() and row_ver = #{f.rowVer}
